  if (!/^[0-9a-fA-F]{64}$/.test(String(fundingTxId || ""))) refuse("the funding transaction id was unreadable.");
  if (!Number.isInteger(Number(fundingVout)) || Number(fundingVout) < 0) refuse("the funding output index was unreadable.");
