export const SATORA_HTLC_ERC20_REFUND_SELECTOR = "0x36504721";
const SATORA_HTLC_REFUND_INTERFACE = ["function refund(bytes32 preimageHash, uint256 amount, address token, address claimAddress, uint256 timelock)"];
