      target: `${pkg}::create_order::create_order`, typeArguments: [usdcType],
      arguments: [tx.object(MAYAN_SUI_FAST_MCTP_STATE), tx.object(MAYAN_SUI_USDC_CURRENCY_ID), orderTicket],
