    target: `${MAYAN_SUI_CCTP_V2_TOKEN_PACKAGE}::deposit_for_burn::deposit_for_burn_with_package_auth`,
    typeArguments: [usdcType, `${pkg}::circle_auth::CircleAuth`],
    arguments: [burnTicket, tx.object(MAYAN_SUI_CCTP_V2_TOKEN_STATE)],
