    target: `${MAYAN_SUI_CCTP_V2_HANDLER_PACKAGE}::handler::burn`,
    arguments: [tx.object(MAYAN_SUI_CCTP_V2_HANDLER_STATE), burnReceipt, burnCoin, tx.object(MAYAN_SUI_DENY_LIST), tx.object(MAYAN_SUI_USDC_TREASURY)],
