    target: `${MAYAN_SUI_CCTP_V2_TOKEN_PACKAGE}::deposit_for_burn::complete_burn`,
    typeArguments: [usdcType, `${MAYAN_SUI_CCTP_V2_HANDLER_PACKAGE}::handler::Auth`],
