      fok: { slippageTolerancePercent: qb.slippageTolerancePercent, retryDurationBlocks: CHAINFLIP_FOK_RETRY_BLOCKS },
      brokerBps: baasCfg.commissionBps, lowLiquidityWarning: qb.lowLiquidityWarning === true,
