export const CCTP_V2_TOKEN_MESSENGER = SATORA_CCTP_TOKEN_MESSENGER_V2;
export const CCTP_V2_MESSAGE_TRANSMITTER = SATORA_CCTP_MESSAGE_TRANSMITTER_V2;
